package com.wormzjl.icheme.client;

import net.minecraft.client.model.geom.PartPose;
import net.minecraft.client.model.geom.builders.CubeListBuilder;
import net.minecraft.client.model.geom.builders.PartDefinition;

/**
 * The respirator's worn model, option C (full face, twin cartridges; batch 2026-11-18-respirator). Generated by
 * {@code tools/respirator-sheets/model.mjs --write} with its texture {@code textures/models/armor/respirator_layer_1.png};
 * change the geometry there and write both again, never by hand.
 */
public final class RespiratorGeometry {
    public static final int TEXTURE_WIDTH = 64;
    public static final int TEXTURE_HEIGHT = 64;
    /** The parts' names, children of the head. */
    public static final java.util.List<String> PARTS = java.util.List.of("mask", "cartridge_left", "cartridge_right");

    private RespiratorGeometry() {
    }

    /** Adds the mask's parts to the head part. */
    public static void build(PartDefinition head) {
        head.addOrReplaceChild("mask", CubeListBuilder.create()
                .texOffs(0, 0).addBox(-3.5F, -7.5F, -4.6F, 7.0F, 7.0F, 1.0F)
                .texOffs(16, 0).addBox(-3.0F, -6.5F, -5.0F, 6.0F, 3.0F, 1.0F)
                .texOffs(30, 0).addBox(-1.5F, -3.5F, -5.4F, 3.0F, 3.0F, 1.0F)
                .texOffs(38, 0).addBox(-1.0F, -3.0F, -6.0F, 2.0F, 2.0F, 1.0F)
                .texOffs(44, 0).addBox(3.75F, -4.5F, -4.0F, 1.0F, 1.0F, 8.0F)
                .texOffs(0, 9).addBox(-4.75F, -4.5F, -4.0F, 1.0F, 1.0F, 8.0F)
                .texOffs(18, 9).addBox(-5.0F, -4.5F, 3.75F, 10.0F, 1.0F, 1.0F)
                .texOffs(40, 9).addBox(-0.5F, -8.75F, -3.75F, 1.0F, 1.0F, 7.0F),
                PartPose.offset(0.0F, 0.0F, 0.0F));
        head.addOrReplaceChild("cartridge_left", CubeListBuilder.create()
                .texOffs(0, 18).addBox(-1.5F, -1.0F, -2.0F, 3.0F, 2.0F, 2.0F)
                .texOffs(10, 18).addBox(-1.0F, -1.5F, -1.9F, 2.0F, 3.0F, 2.0F)
                .texOffs(18, 18).addBox(-0.5F, -0.5F, 0.0F, 1.0F, 1.0F, 1.0F),
                PartPose.offsetAndRotation(2.4F, -1.9F, -4.7F, -0.15F, -0.6F, 0.0F));
        head.addOrReplaceChild("cartridge_right", CubeListBuilder.create()
                .texOffs(22, 18).addBox(-1.5F, -1.0F, -2.0F, 3.0F, 2.0F, 2.0F)
                .texOffs(32, 18).addBox(-1.0F, -1.5F, -1.9F, 2.0F, 3.0F, 2.0F)
                .texOffs(40, 18).addBox(-0.5F, -0.5F, 0.0F, 1.0F, 1.0F, 1.0F),
                PartPose.offsetAndRotation(-2.4F, -1.9F, -4.7F, -0.15F, 0.6F, 0.0F));
    }
}
